from pathlib import Path
def bad_name(rel):
    return os.path.isabs(rel) or ".." in Path(rel).parts
def scan(path,label):
    rows=[json.loads(l) for l in open(path) if l.strip()]
    nrows=0; names=collections.Counter(); strat=collections.Counter(); first=None
    nul_argv=0
    for i,r in enumerate(rows):
        hit=False
        for spec in r.get('inputs',[]):
            for k in (spec.get('files') or {}):
                if bad_name(k):
                    hit=True; names[k]+=1
            for a in spec.get('argv',[]) or []:
                if '\0' in a: nul_argv+=1
        if hit:
            nrows+=1; strat[r['stratum']]+=1
            if first is None: first=i
    print("%s rows=%d  escaping-file rows=%d %s  first at index %s  argv-NUL specs=%d"
          % (label, len(rows), nrows, dict(strat), first, nul_argv))
    print("   escaping names:", names.most_common(12))
