def why(name, files):
    p = PurePosixPath(name)
    if p.is_absolute() or ".." in p.parts:
        return "escapes"
    if "\\" in name or str(p) != name or name == ".":
        return "unnormalised"
    if name == "solution.py" or name.startswith("solution.py/"):
        return "reserved"
    if any(par.as_posix() in files for par in p.parents if str(par) != "."):
        return "collision"
    return None
