    r = json.loads(line)
    hit = set()
    for spec in (r.get('inputs') or []):
        if not isinstance(spec, dict): continue
        files = spec.get('files') or {}
        if not isinstance(files, dict): continue
        for name in files:
            if not isinstance(name, str) or not name: hit.add("empty-or-nonstring"); continue
            w = why(name, files)
            if w: hit.add(w)
    for h in hit: rows[h] += 1
