import json, random
def write(path, families, per_family_native, per_family_repaired, ceiling_families=0, per_family_ceiling=0):
    rows=[]
    for i in range(families):
        fam="construct-%03d"%i
        for j in range(per_family_native):
            rows.append({"case_id":"x","family":fam,"population":"coverage","synth":{"kind":"native"}})
        for j in range(per_family_repaired):
            rows.append({"case_id":"x","family":fam,"population":"coverage","synth":{"kind":"repaired"}})
    for i in range(ceiling_families):
        fam="ceil-%03d"%i
        for j in range(per_family_ceiling):
            rows.append({"case_id":"x","family":fam,"population":"fallback-control","synth":{"kind":"ceiling"}})
    open(path,"w").write("\n".join(json.dumps(r) for r in rows)+"\n")
    return len(rows)
