class Tok:
    # byte-level stub: 1 token per byte, deterministic, prefix-preserving
    eos_token_id = 7
    pad_token_id = 7
    chat_template = "stub"
    special_tokens_map = {"eos_token": "[REDACTED token 10 chars]"}
    def get_vocab(self): return {"a": 0}
    def __len__(self): return 256
    def encode(self, s, add_special_tokens=False):
        return [7] if s == "<|im_end|>" else list(s.encode())
    def __call__(self, s, add_special_tokens=False):
        return {"input_ids": list(s.encode("utf-8"))}
    def apply_chat_template(self, msgs, tokenize=False, add_generation_prompt=False, enable_thinking=False):
        text = "".join("<|im_start|>%s\n%s<|im_end|>\n" % (m["role"], m["content"]) for m in msgs)
        if add_generation_prompt: text += "<|im_start|>assistant\n"
        return list(text.encode("utf-8")) if tokenize else text

