def bound_names(tree,m):
    """every local name that came from module m (alias or from-import)"""
    names=set()
    for n in ast.walk(tree):
        if isinstance(n,ast.Import):
            for a in n.names:
                if a.name.split('.')[0]==m: names.add((a.asname or a.name).split('.')[0])
        elif isinstance(n,ast.ImportFrom):
            if n.level==0 and n.module and n.module.split('.')[0]==m:
                for a in n.names: names.add(a.asname or a.name)
    return names

class Drop(ast.NodeTransformer):
    def __init__(self,names): self.names=names
    def refs(self,node):
        for n in ast.walk(node):
            if isinstance(n,ast.Name) and n.id in self.names: return True
            if isinstance(n,(ast.Import,ast.ImportFrom)): 
                mods=[a.name.split('.')[0] for a in n.names]+([n.module.split('.')[0]] if isinstance(n,ast.ImportFrom) and n.module else [])
                if MOD in mods: return True
        return False
    def generic_visit(self,node):
        for field,old in ast.iter_fields(node):
            if isinstance(old,list) and old and isinstance(old[0],ast.stmt):
                new=[s for s in old if not self.refs(s)]
                if not new: new=[ast.Pass()]
                setattr(node,field,[self.visit(s) for s in new])
            else:
                super().generic_visit(node); break
        return node

def route(p):
    r=subprocess.run([BIN,'route','-c',p],capture_output=True,text=True)
    o=r.stdout.strip()
    return o.split('\t',1) if '\t' in o else [o,'']

