def strip_module(src, m):
    out=[]
    for l in src.splitlines():
        mm=re.match(r'^(\s*)import\s+(.+?)\s*$', l)
        if mm and not l.strip().startswith("#"):
            names=[n.strip() for n in mm.group(2).split(",")]
            keep=[n for n in names if n.split(" as ")[0].strip().split(".")[0]!=m]
            if len(keep)!=len(names):
                if keep: out.append(mm.group(1)+"import "+", ".join(keep))
                elif mm.group(1): out.append(mm.group(1)+"pass")
                continue
        if re.match(r'^\s*from\s+%s(\.[\w.]+)?\s+import\b'%re.escape(m), l):
            ind=re.match(r'^(\s*)',l).group(1)
            if ind: out.append(ind+"pass")
            continue
        out.append(l)
    return "\n".join(out)

