import re
from pathlib import Path

pat = re.compile(r"<<<<<<< [^\n]*\n(.*?)(?:\|\|\|\|\|\|\| [^\n]*\n.*?)?=======\n(.*?)>>>>>>> [^\n]*\n", re.S)

def resolve(path, how):
    s = Path(path).read_text(encoding="utf-8")
    n = len(pat.findall(s))
    def pick(m):
        ours, theirs = m.group(1), m.group(2)          # ours=pr90, theirs=main
        if how == "union-ours-first":
            return ours.rstrip("\n") + "\n" + theirs if ours.strip() and theirs.strip() else (ours or theirs)
        if how == "union-theirs-first":
            return theirs.rstrip("\n") + "\n\n" + ours if ours.strip() and theirs.strip() else (theirs or ours)
        return theirs                                   # "main"
    Path(path).write_text(pat.sub(pick, s), encoding="utf-8")
    left = Path(path).read_text(encoding="utf-8").count("<<<<<<<")
    print("%-42s %d block(s) -> %-18s leftover=%d" % (path, n, how, left))

for f in ("training/tests/test_hf_launch.py", "training/tests/test_levers.py"):
    resolve(f, "union-ours-first")
resolve("CHANGELOG.md", "union-theirs-first")
for f in ("training/STATUS.md", "training/ORCHESTRATION.md", "training/START_NEXT_ROUND.md"):
    resolve(f, "main")

