import json, collections
def scan(path,label):
    rows=[json.loads(l) for l in open(path) if l.strip()]
    hits=collections.Counter()
    rowhit=collections.Counter()
    for r in rows:
        where=set()
        for spec in r.get('inputs',[]):
            for a in spec.get('argv',[]) or []:
                if '\0' in a: where.add('argv')
            for k,v in (spec.get('files') or {}).items():
                if '\0' in k: where.add('files-name')
                if '\0' in v: where.add('files-body')
            if '\0' in (spec.get('stdin') or ''): where.add('stdin')
        if where:
            rowhit[r['stratum']]+=1
            for w in where: hits[w]+=1
    print(label, "rows", len(rows), "NUL rows by stratum", dict(rowhit), "fields", dict(hits))
