def strip_module(src,m):
    out=[]
    for ln in src.splitlines():
        s=ln.strip()
        if re.match(r'^from\s+%s(\.\w+)*\s+import\b'%re.escape(m),s): continue
        mm=re.match(r'^import\s+(.*)$',s)
        if mm:
            names=[n.strip() for n in mm.group(1).split(',')]
            keep=[n for n in names if n.split(' as ')[0].strip().split('.')[0]!=m]
            if not keep: continue
            if len(keep)!=len(names):
                out.append(ln[:len(ln)-len(ln.lstrip())]+'import '+', '.join(keep)); continue
        out.append(ln)
    return '\n'.join(out)
def route(p):
    r=subprocess.run([BIN,'route','-c',p],capture_output=True,text=True)
    o=r.stdout.strip()
    return o.split('\t',1) if '\t' in o else [o,'']
